		public RequestResponse RequestResponse(RequestResponseRequest request)
		{
			string fileName = "";
			Console.WriteLine("FMD is sending an idoc.");
			RequestResponse toRet = null;

			string strIdoc = System.Text.Encoding.ASCII.GetString(request.ReqContent);


			fileName = LogIDoc(FromXML(strIdoc));
			Console.WriteLine("Received idoc and saved to" + fileName + ".");
	
			 
			responseType respType = new responseType();
			respType.InjectDEBXMessageResponse = new responseTypeInjectDEBXMessageResponse();
			respType.InjectDEBXMessageResponse.trackingNumber = new System.IO.FileInfo(fileName).Name;

			toRet = new RequestResponse(respType);

			return toRet;

		}

